<?php
require __DIR__.'/../includes/app.php';admin();require __DIR__.'/content-types.php';$types=contentTypes();
// Preserve old edit links by routing to the record's dedicated section.
if(isset($_GET['id'])){$q=db()->prepare('SELECT kind FROM entries WHERE id=?');$q->execute([(int)$_GET['id']]);$kind=$q->fetchColumn();if(isset($types[$kind])){header('Location: '.$types[$kind]['page'].'?id='.(int)$_GET['id']);exit;}}
